
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_tfvw_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_tfvw", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.156185203543576e+02, 1.119226050231139e+02, 1.068648476938354e+02, 1.000924660888042e+02, 9.130228358394677e+01, 8.038832654411588e+01, 6.766040225188847e+01, 5.404566799920786e+01, 4.098064811806069e+01, 2.922476831662425e+01, 1.559826439937902e+01, 3.503715509596353e+00, 2.181517922570778e+00, 1.789819477254994e+00, 1.307505605763083e+00, 9.380886700668214e-01, 7.447921658946629e-01, 6.524707457147515e-01, 6.036885875352588e-01, 5.743515731063042e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


